import{c as r,Z as t,Q as l,j as s,m as n,o}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"早发白帝城","description":"","frontmatter":{"title":"早发白帝城","author":"李白","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/8.md","filePath":"books/shici/tangshi/8.md"}'),h={name:"books/shici/tangshi/8.md"};function u(c,a,p,d,q,_){const e=t("PoemAuthor"),i=t("PoemNav");return l(),s("div",null,[a[0]||(a[0]=n('<h1 id="早发白帝城" tabindex="-1">早发白帝城 <a class="header-anchor" href="#早发白帝城" aria-label="Permalink to &quot;早发白帝城&quot;">​</a></h1><p><strong>[唐] <a href="/authors/libai.html">李白</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>朝辞白帝彩云间，千里江陵一日还。 两岸猿声啼不住，轻舟已过万重山。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>白帝城：在今重庆市奉节县白帝山上，为东汉公孙述所建</li><li>朝辞：早晨告别</li><li>彩云间：形容白帝城地势高峻，如在彩云之中</li><li>江陵：今湖北省荆州市，距白帝城约一千二百里</li><li>一日还：一天就可以到达</li><li>猿声：猿猴的啼叫声</li><li>啼不住：不停地啼叫</li><li>轻舟：轻快的小船</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>早晨告别高耸入云的白帝城，千里之外的江陵一天就可以到达。两岸猿猴的啼叫声还没有停歇，轻快的小船已经驶过了万重青山。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是李白流放途中遇赦返回时所作，表达了诗人重获自由后的欢快心情。</p><p>首句&quot;朝辞白帝彩云间&quot;，写早晨告别白帝城的情景。&quot;彩云间&quot;三字，既写出了白帝城的高峻地势，又暗示了诗人此时轻松愉悦的心情，仿佛置身仙境。</p><p>次句&quot;千里江陵一日还&quot;，用夸张的手法写行船之快。&quot;千里&quot;与&quot;一日&quot;形成鲜明对比，极言船速之快，也暗示了诗人归心似箭的心情。</p><p>后两句&quot;两岸猿声啼不住，轻舟已过万重山&quot;，是全诗的名句。诗人以猿声的&quot;啼不住&quot;与轻舟的&quot;已过&quot;形成对比，用听觉的延续反衬视觉的飞逝，生动地表现了船行之快。&quot;万重山&quot;既写出了三峡山峦叠嶂的地形特点，又暗示了诗人跨越重重困难的畅快心情。</p><p>全诗气势奔放，节奏明快，将诗人遇赦后的喜悦之情与长江三峡的壮丽景色完美融合，是李白七绝中的精品。</p>',14)),o(e,{name:"李白",years:"701年－762年",desc:"字太白，号青莲居士，又号“谪仙人”，唐代伟大的浪漫主义诗人，被后人誉为“诗仙”。其诗风雄奇豪放，想象丰富，意境奇妙，语言流转自然。",link:"/authors/libai"}),o(i)])}const f=r(h,[["render",u]]);export{b as __pageData,f as default};
